                'INSERT INTO expenses (kind, funding_source, group_id, title, description, category, round_label, amount_cents,
                       expense_date, payer_resident_id, items, notes, status, created_by, reviewed_by, reviewed_at, created_at)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?, ?, ?)',
                [
                    'shared', $funding, $groupId, $title, $note, $category, $roundLabel, $amount,
                    $date, $payerId, $note, 'approved', $adminUserId, $adminUserId,
                    $date . ' 12:00:00', $date . ' 12:00:00',
                ]
            );
            $expenseId = (int) Database::insertId();

            $participantIds = array_map(fn ($key) => $members[$key]['resident_id'], $participants);
            $count = count($participantIds);
            $base = intdiv($amount, $count);
            $remainder = $amount - ($base * $count);
            foreach ($participantIds as $index => $residentId) {
                $share = $base + ($index === 0 ? $remainder : 0);
                Database::run(
                    'INSERT INTO expense_shares (id, expense_id, resident_id, amount_cents) VALUES (?, ?, ?, ?)',
                    [Uuid::v4(), $expenseId, $residentId, $share]
                );
                Database::run(
                    'INSERT INTO ledger_entries (id, resident_id, kind, amount_cents, entry_date, expense_id, note, round_label, source, sort_order, created_by, created_at)
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
                    [
                        Uuid::v4(), $residentId, 'share', -$share, $date, $expenseId,
                        'Share: ' . $title, $roundLabel, 'adjustment', $expenseIndex, $adminUserId,
                        $date . ' 12:00:00',
                    ]
                );
            }
        }

        // A small cleaning rota so the dashboard is useful immediately.
        $chores = [
            ['Hall & common areas', 'hall', 'H', 7],
            ['Kitchen cleaning', 'kitchen', 'K', 7],
            ['Garbage disposal', 'garbage', null, 2],
        ];
        $choreIndex = 0;
        foreach ($chores as [$name, $kind, $spaceCode, $frequency]) {
            $choreId = Uuid::v4();
            $current = $members[$all[$choreIndex % count($all)]]['resident_id'];
            Database::run(
                'INSERT INTO chores (id, name, kind, space_id, frequency_days, rotates, current_resident_id, next_due, active, created_at)
                 VALUES (?, ?, ?, ?, ?, 1, ?, ?, 1, ?)',
                [$choreId, $name, $kind, $spaceCode ? $spaceIds[$spaceCode] : null, $frequency, $current, '2026-10-24', $createdAt]
            );
            foreach ($all as $position => $key) {
                Database::run(
                    'INSERT INTO chore_members (chore_id, resident_id, position) VALUES (?, ?, ?)',
                    [$choreId, $members[$key]['resident_id'], $position]
                );
            }
            $choreIndex++;
        }

        Database::run(
            'INSERT INTO notifications (id, audience, user_id, type, title, body, link, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
            [
                Uuid::v4(), 'user', $members['asifbhai']['user_id'], 'finance',
                'Action required: Round 5 contribution',
                'Pending €11.00 contribution for Round 5. (To be offset directly via upcoming grocery purchases).',
                '/report', '2026-10-24 09:00:00',
            ]
        );
        Database::run(
            'INSERT INTO notifications (id, audience, user_id, type, title, body, link, created_at)
             VALUES (?, ?, NULL, ?, ?, ?, ?, ?)',
            [
                Uuid::v4(), 'admin', 'finance',
                'October audit ledger is live',
                'The financial ledger has been reset and seeded for Oct 2 – Oct 24, 2026. Current pool balance: -€11.27.',
                '/report', '2026-10-24 09:01:00',
            ]
        );

        // Default CMS content so the public homepage keeps working after the wipe.
        $sections = [
            ['hero', 'home', 'hero', 'home', 1, 1, 'Sign in', '/auth'],
            ['feature.expenses', 'home', 'feature', 'receipt', 10, 1, null, null],
            ['feature.cleaning', 'home', 'feature', 'sparkles', 20, 1, null, null],
            ['feature.issues', 'home', 'feature', 'wrench', 30, 1, null, null],
            ['feature.floorplan', 'home', 'feature', 'home', 40, 1, null, null],
            ['about', 'home', 'section', null, 50, 0, null, null],
            ['footer', 'footer', 'section', null, 90, 0, null, null],
        ];
        foreach ($sections as [$code, $area, $kind, $icon, $sort, $visible, $ctaLabel, $ctaHref]) {
            Database::run(
                'INSERT INTO site_sections (code, area, kind, icon, sort, visible, cta_label, cta_href)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
                [$code, $area, $kind, $icon, $sort, $visible, $ctaLabel, $ctaHref]
            );
        }
        $translations = [
            ['hero', 'en', 'Five flatmates, one flat, zero spreadsheets.', 'Everything your shared flat needs: who owes what, whose turn it is to clean, and what needs fixing.', null],
            ['hero', 'de', 'Fünf Mitbewohner, eine Wohnung, null Tabellen.', 'Alles, was eure gemeinsame Wohnung braucht: wer schuldet was, wer wann dran ist zu putzen, und was repariert werden muss.', null],
            ['feature.expenses', 'en', 'Fair expenses', null, 'Split by group or custom shares, claims reviewed by the admin.'],
            ['feature.expenses', 'de', 'Faire Ausgaben', null, 'Nach Gruppe oder individuellen Anteilen splitten; Ansprüche prüft die Verwaltung.'],
            ['feature.cleaning', 'en', 'Cleaning rota', null, 'Duties rotate automatically, with photo proof.'],
            ['feature.cleaning', 'de', 'Putzplan', null, 'Dienste rotieren automatisch, inklusive Fotobeweis.'],
            ['feature.issues', 'en', 'Issues', null, 'Report a broken tap, follow it until resolved.'],
            ['feature.issues', 'de', 'Störungen', null, 'Tropfenden Wasserhahn melden und mitverfolgen, bis er behoben ist.'],
            ['feature.floorplan', 'en', 'Floor plan', null, 'See every room and washroom in 2D or 3D.'],
            ['feature.floorplan', 'de', 'Grundriss', null, 'Jedes Zimmer und Bad in 2D oder 3D sehen.'],
            ['about', 'en', 'About the flat', null, null],
            ['about', 'de', 'Über die Wohngemeinschaft', null, null],
            ['footer', 'en', 'FlatMate Hub', null, null],
            ['footer', 'de', 'FlatMate Hub', null, null],
        ];
        foreach ($translations as [$code, $locale, $heading, $subheading, $body]) {
            Database::run(
                'INSERT INTO site_section_translations (section_code, locale, heading, subheading, body)
                 VALUES (?, ?, ?, ?, ?)',
                [$code, $locale, $heading, $subheading, $body]
            );
        }
        $settings = [
            ['site_name', 'FlatMate Hub'],
            ['default_locale', 'en'],
            ['social_instagram_url', ''],
            ['donations_account', ''],
            ['donations_instructions', ''],
            ['donations_goal', ''],
            ['donations_public', '0'],
        ];
        foreach ($settings as [$key, $value]) {
            Database::run('INSERT INTO site_settings (setting_key, setting_value) VALUES (?, ?)', [$key, $value]);
        }

        Database::run(
            'INSERT INTO audit_log (actor_id, action, entity, entity_id, details, created_at)
             VALUES (?, ?, ?, NULL, ?, ?)',
            [
                $adminUserId, 'reset_finance', 'system',
                json_encode(['period' => '2026-10-02..2026-10-24', 'pool_balance_cents' => -1127], JSON_THROW_ON_ERROR),
                '2026-10-24 09:02:00',
            ]
        );

        try {
            $pdo->exec("CREATE TABLE IF NOT EXISTS schema_migrations (
              version VARCHAR(10) NOT NULL PRIMARY KEY,
              applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
            ) ENGINE=InnoDB");
            $pdo->exec("INSERT IGNORE INTO schema_migrations (version) VALUES ('0009')");
        } catch (Throwable $ignored) {
        }

        $pool = Database::row(
            "SELECT COALESCE(SUM(CASE WHEN kind = 'payment' THEN amount_cents ELSE 0 END), 0) AS contributions
               FROM ledger_entries"
        );
        $purchases = Database::row(
            "SELECT COALESCE(SUM(amount_cents), 0) AS purchases FROM expenses WHERE status = 'approved'"
        );
        $contributionsCents = (int) ($pool['contributions'] ?? 0);
        $purchasesCents = (int) ($purchases['purchases'] ?? 0);

        return [
            'ok' => true,
            'members' => count($members),
            'expenses' => count($expenses),
            'rounds' => count($rounds),
            'contributions_cents' => $contributionsCents,
            'purchases_cents' => $purchasesCents,
            'pool_balance_cents' => $contributionsCents - $purchasesCents,
        ];
    } finally {
        $pdo->exec('SET FOREIGN_KEY_CHECKS = 1');
    }
}

if (PHP_SAPI === 'cli' && realpath($_SERVER['SCRIPT_FILENAME'] ?? '') === __FILE__) {
    try {
        $result = flatmateResetRun('cli', 'cli');
        echo json_encode($result, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) . "\n";
    } catch (Throwable $error) {
        fwrite(STDERR, 'Reset failed: ' . $error->getMessage() . "\n");
        exit(1);
    }
}
